&lt;/div&gt;&lt;div&gt;&lt;p style=&quot;margin:0.0cm 0.0cm 0.0cm 18.0pt;font-size:11.0pt;font-family:Arial, sans-serif&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-size:9.0pt&quot;&gt;Wie ben jij?&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul style=&quot;margin-bottom:0.0cm;margin-top:0.0px&quot;&gt;
&lt;li style=&quot;margin:0.0cm 0.0cm 0.0cm 24.0px;font-size:11.0pt;font-family:Arial, sans-serif&quot;&gt;&lt;span style=&quot;font-size:9.0pt&quot;&gt;Je volgt de Hbo-opleiding Human Resource Management.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin:0.0cm 0.0cm 0.0cm 24.0px;font-size:11.0pt;font-family:Arial, sans-serif&quot;&gt;&lt;span style=&quot;font-size:9.0pt&quot;&gt;Je bent proactief, leergierig en kunt goed samenwerken.&lt;/span&gt;&lt;/li&gt;
